mapper.select:
select act.ACT_ID as actId, act.ACT_CODE AS actCode, (select dc.DICT_CN_DESC from rm_sys_dict dc where dc.DICT_TYPE_CD='2001' and dc.DICT_CD=act.ACT_CODE) as actNode, case act.ACT_CODE when '20010001' then act. ACT_RECEIVER when '20010007' then (select uu.USER_NM from RM_SYS_USER_INFO uu where ta.HANDLE_PERSON=uu.USER_MOBILE) else (select GROUP_CONCAT(ass.ASS_ASSIGNEE SEPARATOR ",") from TASK_ACT_ASSIGNEE ass where ass.ASS_ACT_ID=act.ACT_ID and ass.ASS_STATE!='03') end as actReceiver, act.ACT_RECEIVE_TM as actReceiveTm, DATE_FORMAT(act.ACT_RECEIVE_TM,"%Y-%m-%d %H:%i:%s") as actReceiveTime, act.ACT_HAND_NM as actHandNm, act.ACT_HANDLER as actHandler, act.ACT_HANDLE_TM as actHandleTm, DATE_FORMAT(act.ACT_HANDLE_TM,"%Y-%m-%d %H:%i:%s") as actHandleTime, act.ACT_COMMENT as actComment, case act.ACT_STATE when '01' then '已处理' else '未处理' end as actState, act.ACT_INST_ID as actInstId, act.ACT_MARK as actMark, act.ACT_PICTURE as actPicture from TASK_ACT_INST act left join RM_TASK_INFO ta on ta.PROC_INST_ID=act.ACT_INST_ID where act.ACT_STATE !='03'
and act.act_inst_id = #{procInstId}
and act.ACT_ID = #{actId}

select act.ACT_ID as actId, act.ACT_CODE AS actCode, (select dc.DICT_CN_DESC from rm_sys_dict dc where dc.DICT_TYPE_CD='2001' and dc.DICT_CD=act.ACT_CODE) as actNode, case act.ACT_CODE when '20010001' then act. ACT_RECEIVER when '20010007' then (select uu.USER_NM from RM_SYS_USER_INFO uu where ta.HANDLE_PERSON=uu.USER_MOBILE) else (select GROUP_CONCAT(ass.ASS_ASSIGNEE SEPARATOR ",") from TASK_ACT_ASSIGNEE ass where ass.ASS_ACT_ID=act.ACT_ID and ass.ASS_STATE!='03') end as actReceiver, DATE_FORMAT(act.ACT_RECEIVE_TM,"%Y-%m-%d %H:%i:%s") as actReceiveTime, act.ACT_HAND_NM as actHandNm, act.ACT_HANDLER as actHandler, DATE_FORMAT(act.ACT_HANDLE_TM,"%Y-%m-%d %H:%i:%s") as actHandleTime, act.ACT_COMMENT as actComment, case act.ACT_STATE when '01' then '已处理' else '未处理' end as actState, act.ACT_INST_ID as actInstId, act.ACT_MARK as actMark, act.ACT_PICTURE as actPicture from TASK_ACT_INST act left join RM_TASK_INFO ta on ta.PROC_INST_ID=act.ACT_INST_ID where act.ACT_STATE !='03'
and act.act_inst_id = #{procInstId}
and act.ACT_ID = #{actId}
